  unfold Cin_1RB1LB_1RC1LD_0LD0RC_1RB0LA, cden, AI0_1RB1LB_1RC1LD_0LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LB_1RC1LD_0LD0RC_1RB0LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_011_111_1 q0 ++ []) [] i AI1_1RB1LB_1RC1LD_0LD0RC_1RB0LA) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 v i q0 E) as (_ & H2).
  unfold Cin_1RB1LB_1RC1LD_0LD0RC_1RB0LA, cden, AI1_1RB1LB_1RC1LD_0LD0RC_1RB0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
