  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LB_1RC1LD_0LD0RC_1RB0LA : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (8 * i + 8), (cden (Ap_Alph_011_111_1 q0 ++ []) [] i AI1_1RB1LB_1RC1LD_0LD0RC_1RB0LA).
  split; [lia|]. split; [| exact (gen_1RB1LB_1RC1LD_0LD0RC_1RB0LA v i q0 E)].
  rewrite (gsn_1RB1LB_1RC1LD_0LD0RC_1RB0LA v i q0 E).
  exact (srun_sound tm false true chn_1RB1LB_1RC1LD_0LD0RC_1RB0LA AI0_1RB1LB_1RC1LD_0LD0RC_1RB0LA AI1_1RB1LB_1RC1LD_0LD0RC_1RB0LA 8 8
           run_inner_1RB1LB_1RC1LD_0LD0RC_1RB0LA (Ap_Alph_011_111_1 q0 ++ []) [] i
           ltac:(discriminate) ltac:(reflexivity)).
