  - destruct (gz_1RB1LC_0LA0RB_1LA__________ p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB1LC_0LA0RB_1LA__________ Z0_1RB1LC_0LA0RB_1LA__________ Z1_1RB1LC_0LA0RB_1LA__________ 0 2
               run_z_1RB1LC_0LA0RB_1LA__________ (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB1LC_0LA0RB_1LA__________ p j' q0 E) as (HA & HB).
    exists (4 * j' + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LC_0LA0RB_1LA__________ P0_1RB1LC_0LA0RB_1LA__________ P1_1RB1LC_0LA0RB_1LA__________ 4 6
               run_p_1RB1LC_0LA0RB_1LA__________ (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
