    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_101_111_1 LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift Alph_101_111_11.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_1RB1LC_0LA0RC_0RD1LB_1LA1RD (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_1RB1LC_0LA0RC_0RD1LB_1LA1RD.

(** 1RB1LC_0LA0RC_0RD1LB_1LA1RD *)
(** 1RB1LC_0LA0RC_0RD1LB_1LA1RD -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB1LC_0LA0RC_0RD1LB_1LA1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S0 DL StA | StB, S1 => mk S0 DR StC
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DL StB
  | StD, S0 => mk S1 DL StA | StD, S1 => mk S1 DR StD end.

(** Its mirror 1LB1RC_0RA0LC_0LD1RB_1RA1LD: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_1RB1LC_0LA0RC_0RD1LB_1LA1RD : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DL StB | StA, S1 => mk S1 DR StC
  | StB, S0 => mk S0 DR StA | StB, S1 => mk S0 DL StC
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StB
  | StD, S0 => mk S1 DR StA | StD, S1 => mk S1 DL StD end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LC_0LA0RC_0RD1LB_1LA1RD : list Instr := [].
Definition tmw_1RB1LC_0LA0RC_0RD1LB_1LA1RD : TM := tm_wrap_trs tmm_1RB1LC_0LA0RC_0RD1LB_1LA1RD pins_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
Local Notation tm := tmw_1RB1LC_0LA0RC_0RD1LB_1LA1RD.

Lemma mirror_ok_1RB1LC_0LA0RC_0RD1LB_1LA1RD : mirror_tm tm_1RB1LC_0LA0RC_0RD1LB_1LA1RD = tmm_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_1RB1LC_0LA0RC_0RD1LB_1LA1RD (p : positive) : cconf := (StC, (Ap_Alph_101_111_1 p ++ [S0;S1;S1;S1;S0], S0, [])).
Local Notation Cc := Cc_1RB1LC_0LA0RC_0RD1LB_1LA1RD.

(** ** The certificate *)

Definition A0_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition A1_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chi_1RB1LC_0LA0RC_0RD1LB_1LA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 5; SWin 1; SUnrotL 1].

Lemma run_int_1RB1LC_0LA0RC_0RD1LB_1LA1RD : srun tm false true chi_1RB1LC_0LA0RC_0RD1LB_1LA1RD A0_1RB1LC_0LA0RC_0RD1LB_1LA1RD = Some (A1_1RB1LC_0LA0RC_0RD1LB_1LA1RD, 8, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S0;S1] 1 1 [S1;S0;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_101_111_11 at StC *)
Definition Cin_1RB1LC_0LA0RC_0RD1LB_1LA1RD (v : positive) : cconf := (StC, (Ap_Alph_101_111_11 v ++ [S1;S1;S1], S0, [])).
Local Notation Cin := Cin_1RB1LC_0LA0RC_0RD1LB_1LA1RD.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall n, Ap_Alph_101_111_11 (pow2 n) = rep [S1;S0;S1] n ++ [S1;S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S0;S1]) S0 (mkS [] [] 0 0 []).
Definition AI1_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_1RB1LC_0LA0RC_0RD1LB_1LA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 5; SWin 1; SUnrotL 1].

Lemma run_inner_1RB1LC_0LA0RC_0RD1LB_1LA1RD : srun tm false true chn_1RB1LC_0LA0RC_0RD1LB_1LA1RD AI0_1RB1LC_0LA0RC_0RD1LB_1LA1RD = Some (AI1_1RB1LC_0LA0RC_0RD1LB_1LA1RD, 8, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S0;S1] 1 0 [S1;S1;S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition chb_1RB1LC_0LA0RC_0RD1LB_1LA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 5; SWin 1; SUnrotL 1].

Lemma run_boot_1RB1LC_0LA0RC_0RD1LB_1LA1RD : srun tm true true chb_1RB1LC_0LA0RC_0RD1LB_1LA1RD B0_1RB1LC_0LA0RC_0RD1LB_1LA1RD = Some (BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD, 8, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LC_0LA0RC_0RD1LB_1LA1RD : sconf := mkC StC (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LC_0LA0RC_0RD1LB_1LA1RD : list lstep := [SRotL 1; SWin 1; SCycL 3 0; SWin 4; SWinL 8; SCycR 5; SWin 1; SWinR 4; SFoldL 1].

Lemma run_exit_1RB1LC_0LA0RC_0RD1LB_1LA1RD : srun tm true true che_1RB1LC_0LA0RC_0RD1LB_1LA1RD BE0_1RB1LC_0LA0RC_0RD1LB_1LA1RD = Some (B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD, 8, 18).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_101_111_1 q0 ++ [S0;S1;S1;S1;S0]) [] j A0_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
Proof.
  intros p j q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LC_0LA0RC_0RD1LB_1LA1RD, cden, A0_1RB1LC_0LA0RC_0RD1LB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  cden (Ap_Alph_101_111_1 q0 ++ [S0;S1;S1;S1;S0]) [] j A1_1RB1LC_0LA0RC_0RD1LB_1LA1RD = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_101_111_1.cview_some_Alph_101_111_1 p j q0 E) as (_ & H2).
  unfold Cc_1RB1LC_0LA0RC_0RD1LB_1LA1RD, cden, A1_1RB1LC_0LA0RC_0RD1LB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. exists (8 * j + 4). split; [lia|].
  rewrite (gsi_1RB1LC_0LA0RC_0RD1LB_1LA1RD p j q0 E).
  rewrite (srun_sound tm false true chi_1RB1LC_0LA0RC_0RD1LB_1LA1RD A0_1RB1LC_0LA0RC_0RD1LB_1LA1RD A1_1RB1LC_0LA0RC_0RD1LB_1LA1RD 8 4
             run_int_1RB1LC_0LA0RC_0RD1LB_1LA1RD (Ap_Alph_101_111_1 q0 ++ [S0;S1;S1;S1;S0]) [] j
             ltac:(discriminate) ltac:(reflexivity)).
  f_equal. exact (gei_1RB1LC_0LA0RC_0RD1LB_1LA1RD p j q0 E).
Qed.

Lemma gso_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
Proof.
  intros p j E. destruct (Alph_101_111_1.cview_none_Alph_101_111_1 p j E) as (H1 & _).
  unfold Cc_1RB1LC_0LA0RC_0RD1LB_1LA1RD, cden, B0_1RB1LC_0LA0RC_0RD1LB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_101_111_1.cview_none_Alph_101_111_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD
             = (StC, (rep [S1;S0;S1] (S j) ++ [S1;S0;S1;S1;S1], S0, []))).
  { unfold cden, B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S1;S0;S1] (S j) ++ [S1;S0;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_1RB1LC_0LA0RC_0RD1LB_1LA1RD. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB1LC_0LA0RC_0RD1LB_1LA1RD. reflexivity.
Qed.

Lemma gsn_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ap_Alph_101_111_11 q0 ++ [S1;S1;S1]) [] i AI0_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
Proof.
  intros v i q0 E. destruct (Alph_101_111_11.cview_some_Alph_101_111_11 v i q0 E) as (H1 & _).
  unfold Cin_1RB1LC_0LA0RC_0RD1LB_1LA1RD, cden, AI0_1RB1LC_0LA0RC_0RD1LB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_101_111_11 q0 ++ [S1;S1;S1]) [] i AI1_1RB1LC_0LA0RC_0RD1LB_1LA1RD) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (Alph_101_111_11.cview_some_Alph_101_111_11 v i q0 E) as (_ & H2).
  unfold Cin_1RB1LC_0LA0RC_0RD1LB_1LA1RD, cden, AI1_1RB1LC_0LA0RC_0RD1LB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (8 * i + 4), (cden (Ap_Alph_101_111_11 q0 ++ [S1;S1;S1]) [] i AI1_1RB1LC_0LA0RC_0RD1LB_1LA1RD).
  split; [lia|]. split; [| exact (gen_1RB1LC_0LA0RC_0RD1LB_1LA1RD v i q0 E)].
  rewrite (gsn_1RB1LC_0LA0RC_0RD1LB_1LA1RD v i q0 E).
  exact (srun_sound tm false true chn_1RB1LC_0LA0RC_0RD1LB_1LA1RD AI0_1RB1LC_0LA0RC_0RD1LB_1LA1RD AI1_1RB1LC_0LA0RC_0RD1LB_1LA1RD 8 4
           run_inner_1RB1LC_0LA0RC_0RD1LB_1LA1RD (Ap_Alph_101_111_11 q0 ++ [S1;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 1/0
    trailing blanks. *)
Lemma gbo_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall j, lift (cden [] [] j BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD = (StC, ((rep [S1;S0;S1] j ++ [S1;S1;S1;S1;S1]) ++ [S0], S0, []))).
  { unfold cden, BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StC, (rep [S1;S0;S1] j ++ [S1;S1;S1;S1;S1], S0, []))).
  { unfold Cin_1RB1LC_0LA0RC_0RD1LB_1LA1RD. rewrite epow2_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_1RB1LC_0LA0RC_0RD1LB_1LA1RD. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LC_0LA0RC_0RD1LB_1LA1RD.
Proof.
  intro j.
  destruct (Alph_101_111_11.cview_none_Alph_101_111_11 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_1RB1LC_0LA0RC_0RD1LB_1LA1RD, cden, BE0_1RB1LC_0LA0RC_0RD1LB_1LA1RD; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LC_0LA0RC_0RD1LB_1LA1RD p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LC_0LA0RC_0RD1LB_1LA1RD p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LA0RC_0RD1LB_1LA1RD j)].
    rewrite (gso_1RB1LC_0LA0RC_0RD1LB_1LA1RD p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LA0RC_0RD1LB_1LA1RD B0_1RB1LC_0LA0RC_0RD1LB_1LA1RD BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD 8 4
             run_boot_1RB1LC_0LA0RC_0RD1LB_1LA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 18), (cden [] [] j B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD).
    split; [| exact (geo_1RB1LC_0LA0RC_0RD1LB_1LA1RD p j E)].
    rewrite (gxi_1RB1LC_0LA0RC_0RD1LB_1LA1RD j).
    exact (srun_sound tm true true che_1RB1LC_0LA0RC_0RD1LB_1LA1RD BE0_1RB1LC_0LA0RC_0RD1LB_1LA1RD B1_1RB1LC_0LA0RC_0RD1LB_1LA1RD 8 18
             run_exit_1RB1LC_0LA0RC_0RD1LB_1LA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.

(** A state firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma visx_1RB1LC_0LA0RC_0RD1LB_1LA1RD : forall (l : list lstep) (q : St),
  srun_st tm true true l BE0_1RB1LC_0LA0RC_0RD1LB_1LA1RD = Some q ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ fst e = q.
Proof.
  intros l q Hst p j E.
  apply (vis_via_fill tm Cc Cin lapin_1RB1LC_0LA0RC_0RD1LB_1LA1RD q p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD). split;
      [| exact (gbo_1RB1LC_0LA0RC_0RD1LB_1LA1RD j)].
    rewrite (gso_1RB1LC_0LA0RC_0RD1LB_1LA1RD p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LA0RC_0RD1LB_1LA1RD B0_1RB1LC_0LA0RC_0RD1LB_1LA1RD BB1_1RB1LC_0LA0RC_0RD1LB_1LA1RD 8 4
