Lemma gz_1RB1LC_0LA0RC_1LA1LD_0RD0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB1LC_0LA0RC_1LA1LD_0RD0RB /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB1LC_0LA0RC_1LA1LD_0RD0RB = Cc (Pos.succ p).
