    rewrite (srun_sound tm false true chz_1RB1LC_0LA0RC_1LA1LD_0RD0RB Z0_1RB1LC_0LA0RC_1LA1LD_0RD0RB Z1_1RB1LC_0LA0RC_1LA1LD_0RD0RB 0 2
