    exists (6 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB1LC_0LA0RC_1LA1LD_0RD0RB P0_1RB1LC_0LA0RC_1LA1LD_0RD0RB P1_1RB1LC_0LA0RC_1LA1LD_0RD0RB 6 8
