    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA0RC_1LA1LD_0RD0RB B0_1RB1LC_0LA0RC_1LA1LD_0RD0RB B1_1RB1LC_0LA0RC_1LA1LD_0RD0RB 6 8 p j' [] []).
    + exact run_ovf_1RB1LC_0LA0RC_1LA1LD_0RD0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LA0RC_1LA1LD_0RD0RB p j' E).
    + exact (geo_1RB1LC_0LA0RC_1LA1LD_0RD0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LA0RC_1LA1LD_0RD0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
