(** ** The lap *)

Lemma lap_1RB1LC_0LA0RD_1RD0LC_1LA0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
