  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_0LA0RD_1RD0LC_1LA0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA0RD_1RD0LC_1LA0RB B0_1RB1LC_0LA0RD_1RD0LC_1LA0RB B1_1RB1LC_0LA0RD_1RD0LC_1LA0RB 6 12 p j' [] []).
    + exact run_ovf_1RB1LC_0LA0RD_1RD0LC_1LA0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LA0RD_1RD0LC_1LA0RB p j' E).
    + exact (geo_1RB1LC_0LA0RD_1RD0LC_1LA0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LA0RD_1RD0LC_1LA0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 6.
  assert (H : match csteps tm 6 c0 with
