(** ** Bootstrap *)

Lemma boot_1RB1LC_0LA0RD_1RD1LA____1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
