    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LC_0LA0RD_1RD1LA____1RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LA0RD_1RD1LA____1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LA0RD_1RD1LA____1RB (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LA0RD_1RD1LA____1RB [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_0LA0RD_1RD1LA____1RB
      with (l := [SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
