  - destruct (lapi_1RB1LC_0LA1RA_0RB1LD_0LC0RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA1RA_0RB1LD_0LC0RB B0_1RB1LC_0LA1RA_0RB1LD_0LC0RB B1_1RB1LC_0LA1RA_0RB1LD_0LC0RB 4 20 p j' [] []).
    + exact run_ovf_1RB1LC_0LA1RA_0RB1LD_0LC0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LC_0LA1RA_0RB1LD_0LC0RB p j' E).
    + exact (geo_1RB1LC_0LA1RA_0RB1LD_0LC0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LA1RA_0RB1LD_0LC0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 17.
  assert (H : match csteps tm 17 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

