Lemma fireo_1RB1LC_0LA1RB_1LA0RD_0LB1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LA1RB_1LA0RD_0LB1RD = Some t ->
  forall p j, cview p = (S j, None) ->
