(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_1RB1LC_0LA1RB_1LD0RB_0RD1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_1RB1LC_0LA1RB_1LD0RB_0RD1LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin2 lapin2_1RB1LC_0LA1RB_1LD0RB_0RD1LA p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin (pow2 j))).
    { exists (6 * j + 8), (cden [] [] j BB1_1RB1LC_0LA1RB_1LD0RB_0RD1LA).
      split; [lia|]. split; [| exact (gbo_1RB1LC_0LA1RB_1LD0RB_0RD1LA j)].
      rewrite (gso_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j E).
      exact (srun_sound tm true true chb_1RB1LC_0LA1RB_1LD0RB_0RD1LA B0_1RB1LC_0LA1RB_1LD0RB_0RD1LA BB1_1RB1LC_0LA1RB_1LD0RB_0RD1LA 6 8
               run_boot_1RB1LC_0LA1RB_1LD0RB_0RD1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                  /\ lift c = lift (Cin2 (pow2 j))).
    { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LA1RB_1LD0RB_0RD1LA p (pow2 j) (pow2 j));
        [exact HB1|].
      exists (6 * j + 4), (cden [] [] j BM1_1RB1LC_0LA1RB_1LD0RB_0RD1LA).
      split; [| exact (gbo2_1RB1LC_0LA1RB_1LD0RB_0RD1LA j)].
      rewrite (gxi_1RB1LC_0LA1RB_1LD0RB_0RD1LA j).
      exact (srun_sound tm true true chm_1RB1LC_0LA1RB_1LD0RB_0RD1LA BM0_1RB1LC_0LA1RB_1LD0RB_0RD1LA BM1_1RB1LC_0LA1RB_1LD0RB_0RD1LA 6 4
               run_shift_1RB1LC_0LA1RB_1LD0RB_0RD1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
    exact HB2.
  - exists (6 * j + 8), (cden [] [] j B1_1RB1LC_0LA1RB_1LD0RB_0RD1LA).
    split; [| exact (geo_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j E)].
    rewrite (gxi2_1RB1LC_0LA1RB_1LD0RB_0RD1LA j).
    exact (srun_sound tm true true che_1RB1LC_0LA1RB_1LD0RB_0RD1LA BE0_1RB1LC_0LA1RB_1LD0RB_0RD1LA B1_1RB1LC_0LA1RB_1LD0RB_0RD1LA 6 8
             run_exit_1RB1LC_0LA1RB_1LD0RB_0RD1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LC_0LA1RB_1LD0RB_0RD1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LC_0LA1RB_1LD0RB_0RD1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 1.
  assert (H : match csteps tm 1 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 1 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LA1RB_1LD0RB_0RD1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LA1RB_1LD0RB_0RD1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LA1RB_1LD0RB_0RD1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LA1RB_1LD0RB_0RD1LA : forall t, ~ In t pins_1RB1LC_0LA1RB_1LD0RB_0RD1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LA1RB_1LD0RB_0RD1LA.
  destruct t as [q b]; destruct q, b.
