(** ** The lap *)

Lemma lap_1RB1LC_0LA1RB_1LD0RB_1LA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
