    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LA1RB_1LD0RB_1LA1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LA1RB_1LD0RB_1LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LA1RB_1LD0RB_1LA1LA (StC, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LA1RB_1LD0RB_1LA1LA [SRotL 1; SWin 1; SCycL 3 0; SWin 1] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_0LA1RB_1LD0RB_1LA1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LA1RB_1LD0RB_1LA1LA (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LA1RB_1LD0RB_1LA1LA [SRotL 1; SWin 1; SCycL 3 0; SWin 3; SWinL 2] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LA1RB_1LD0RB_1LA1LA (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LA1RB_1LD0RB_1LA1LA [SRotL 1; SWin 1; SCycL 3 0; SWin 2] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LC_0LA1RB_1LD0RB_1LA1LA : NeverQuasiHaltsTr tm_1RB1LC_0LA1RB_1LD0RB_1LA1LA.
Proof.
  apply (glue_neverqhtr tm_1RB1LC_0LA1RB_1LD0RB_1LA1LA pins_1RB1LC_0LA1RB_1LD0RB_1LA1LA Cc 1).
