(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB1LC_0LA1RB_1LD0RB_1LA1LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Jp q0 ++ [S0]) [] 0 Z0_1RB1LC_0LA1RB_1LD0RB_1LA1LC /\
  cden (Jp q0 ++ [S0]) [] 0 Z1_1RB1LC_0LA1RB_1LD0RB_1LA1LC = Cc (Pos.succ p).
