  apply (fire_of_run_instr tm Cc true true l B0_1RB1LC_0LA1RB_1LD0RB_1RB1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LA1RB_1LD0RB_1RB1LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1LC_0LA1RB_1LD0RB_1RB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LA1RB_1LD0RB_1RB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 6), (cden [] [] j BB1_1RB1LC_0LA1RB_1LD0RB_1RB1LA).
    split; [lia|]. split; [| exact (gbo_1RB1LC_0LA1RB_1LD0RB_1RB1LA j)].
    rewrite (gso_1RB1LC_0LA1RB_1LD0RB_1RB1LA p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LA1RB_1LD0RB_1RB1LA B0_1RB1LC_0LA1RB_1LD0RB_1RB1LA BB1_1RB1LC_0LA1RB_1LD0RB_1RB1LA 6 6
             run_boot_1RB1LC_0LA1RB_1LD0RB_1RB1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LA1RB_1LD0RB_1RB1LA p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_1RB1LC_0LA1RB_1LD0RB_1RB1LA).
    split; [| exact (gbo2_1RB1LC_0LA1RB_1LD0RB_1RB1LA j)].
    rewrite (gxi_1RB1LC_0LA1RB_1LD0RB_1RB1LA j).
    exact (srun_sound tm true true chm_1RB1LC_0LA1RB_1LD0RB_1RB1LA BM0_1RB1LC_0LA1RB_1LD0RB_1RB1LA BM1_1RB1LC_0LA1RB_1LD0RB_1RB1LA 6 4
             run_shift_1RB1LC_0LA1RB_1LD0RB_1RB1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_1RB1LC_0LA1RB_1LD0RB_1RB1LA t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_1RB1LC_0LA1RB_1LD0RB_1RB1LA xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_1RB1LC_0LA1RB_1LD0RB_1RB1LA j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LA1RB_1LD0RB_1RB1LA : forall t, ~ In t pins_1RB1LC_0LA1RB_1LD0RB_1RB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LC_0LA1RB_1LD0RB_1RB1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LA1RB_1LD0RB_1RB1LA (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LA1RB_1LD0RB_1RB1LA [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
