    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 1]).
