  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LC_0LA1RB_1LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1; SWinL 3; SCycR 3; SWin 1; SUnrotL 1; SRotL 1; SWin 1; SRotL 1; SWin 5; SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LC_0LA1RB_1LD0RB_1RB1LA : NeverQuasiHaltsTr tm_1RB1LC_0LA1RB_1LD0RB_1RB1LA.
Proof.
  apply (glue_neverqhtr tm_1RB1LC_0LA1RB_1LD0RB_1RB1LA pins_1RB1LC_0LA1RB_1LD0RB_1RB1LA Cc 1).
