Lemma fireo_1RB1LC_0LA1RB_1LD0RB_1RC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LA1RB_1LD0RB_1RC1LA = Some t ->
