    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LA1RD_0RB0LA_1LA1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LA1RD_0RB0LA_1LA1RB = Some t ->
