(** ** The lap *)

Lemma lap_1RB1LC_0LA1RD_0RB0LA_1LA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
