    apply (lap_of_run tm Cc true true cho_1RB1LC_0LA1RD_0RB0LA_1LA1RD B0_1RB1LC_0LA1RD_0RB0LA_1LA1RD B1_1RB1LC_0LA1RD_0RB0LA_1LA1RD 4 9 p j' [] []).
    + exact run_ovf_1RB1LC_0LA1RD_0RB0LA_1LA1RD.
    + reflexivity.
