(** 1RB1LC_0LA1RD_0RB1LA_0LC0RB *)
Definition tm_1RB1LC_0LA1RD_0RB1LA_0LC0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S0 DL StA | StB, S1 => mk S1 DR StD
  | StC, S0 => mk S0 DR StB | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S0 DL StC | StD, S1 => mk S0 DR StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LC_0LA1RD_0RB1LA_0LC0RB : list Instr := [].
Definition tmw_1RB1LC_0LA1RD_0RB1LA_0LC0RB : TM := tm_wrap_trs tm_1RB1LC_0LA1RD_0RB1LA_0LC0RB pins_1RB1LC_0LA1RD_0RB1LA_0LC0RB.
Local Notation tm := tmw_1RB1LC_0LA1RD_0RB1LA_0LC0RB.

