  apply (nested_overflow_lift tm Cc Cin3 lapin3_1RB1LC_0LA1RD_0RB1LA_0LC0RB p (pow2 j)).
  - assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
