    split; [lia|]. split; [| exact (gbo_1RB1LC_0LA1RD_0RB1LA_0LC0RB j)].
    rewrite (gso_1RB1LC_0LA1RD_0RB1LA_0LC0RB p j E).
    exact (srun_sound tm true true chb_1RB1LC_0LA1RD_0RB1LA_0LC0RB B0_1RB1LC_0LA1RD_0RB1LA_0LC0RB BB1_1RB1LC_0LA1RD_0RB1LA_0LC0RB 4 4
             run_boot_1RB1LC_0LA1RD_0RB1LA_0LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LC_0LA1RD_0RB1LA_0LC0RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 7), (cden [] [] j BM1_1RB1LC_0LA1RD_0RB1LA_0LC0RB).
    split; [| exact (gbo2_1RB1LC_0LA1RD_0RB1LA_0LC0RB j)].
    rewrite (gxi_1RB1LC_0LA1RD_0RB1LA_0LC0RB j).
    exact (srun_sound tm true true chm_1RB1LC_0LA1RD_0RB1LA_0LC0RB BM0_1RB1LC_0LA1RD_0RB1LA_0LC0RB BM1_1RB1LC_0LA1RD_0RB1LA_0LC0RB 4 7
             run_shift_1RB1LC_0LA1RD_0RB1LA_0LC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB3 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin3 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin2 Cin3 lapin2_1RB1LC_0LA1RD_0RB1LA_0LC0RB p (pow2 j) (pow2 j));
      [exact HB2|].
    exists (4 * j + 8), (cden [] [] j BM31_1RB1LC_0LA1RD_0RB1LA_0LC0RB).
