    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LC_0LA1RD_0RB1LA_0RB0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LC_0LA1RD_0RB1LA_0RB0LB = Some t ->
