    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LC_0LA1RD_0RB1LA_0RB0LB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LC_0LA1RD_0RB1LA_0RB0LB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LC_0LA1RD_0RB1LA_0RB0LB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
