  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LC_0LA1RD_0RB1LA_0RB0LB t p (pow2 j)).
  - exists (6 * j + 8), (cden [] [] j BB1_1RB1LC_0LA1RD_0RB1LA_0RB0LB). split;
      [| exact (gbo_1RB1LC_0LA1RD_0RB1LA_0RB0LB j)].
