    exact (srun_sound tm true true chb_1RB1LC_0LA1RD_0RB1LA_0RB0LB B0_1RB1LC_0LA1RD_0RB1LA_0RB0LB BB1_1RB1LC_0LA1RD_0RB1LA_0RB0LB 6 8
             run_boot_1RB1LC_0LA1RD_0RB1LA_0RB0LB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LC_0LA1RD_0RB1LA_0RB0LB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LC_0LA1RD_0RB1LA_0RB0LB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LC_0LA1RD_0RB1LA_0RB0LB : forall t, ~ In t pins_1RB1LC_0LA1RD_0RB1LA_0RB0LB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
