    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LA1RD_0RB1LA_0RB0RB [SWinR 2; SCycL 2 0; SWin 4] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtr_1RB1LC_0LA1RD_0RB1LA_0RB0RB : NeverQuasiHaltsTr tm_1RB1LC_0LA1RD_0RB1LA_0RB0RB.
