(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LC_0LA1RD_0RB1LA_1LA0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_1RB1LC_0LA1RD_0RB1LA_1LA0RB.
