    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LC_0LA1RD_0RB1LA_1LB0RB [SWinR 2; SCycL 2 0; SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LC_0LA1RD_0RB1LA_1LB0RB (StD, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LC_0LA1RD_0RB1LA_1LB0RB [SWinR 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
